     1|import React, { memo, useRef } from 'react';
     2|import { View, Text, StyleSheet, TouchableOpacity, Animated } from 'react-native';
     3|import { CheckCircle, ChevronRight } from 'lucide-react-native';
     4|import Colors from '@/constants/colors';
     5|import { Mountain, categoryLabels } from '@/constants/mountains';
     6|import MountainIcon from '@/components/MountainIcon';
     7|
     8|interface MountainCardProps {
     9|  mountain: Mountain;
    10|  isSummited: boolean;
    11|  onPress: () => void;
    12|}
    13|
    14|function MountainCardComponent({ mountain, isSummited, onPress }: MountainCardProps) {
    15|  const scaleAnim = useRef(new Animated.Value(1)).current;
    16|
    17|  const handlePressIn = () => {
    18|    Animated.spring(scaleAnim, {
    19|      toValue: 0.97,
    20|      useNativeDriver: true,
    21|    }).start();
    22|  };
    23|
    24|  const handlePressOut = () => {
    25|    Animated.spring(scaleAnim, {
    26|      toValue: 1,
    27|      friction: 3,
    28|      useNativeDriver: true,
    29|    }).start();
    30|  };
    31|
    32|  const categoryColor = Colors.categoryColors[mountain.category] ?? Colors.accent;
    33|
    34|  return (
    35|    <Animated.View style={[styles.cardWrapper, { transform: [{ scale: scaleAnim }] }]}>
    36|      <TouchableOpacity
    37|        style={[styles.card, isSummited && styles.cardSummited]}
    38|        onPress={onPress}
    39|        onPressIn={handlePressIn}
    40|        onPressOut={handlePressOut}
    41|        activeOpacity={0.9}
    42|        testID={`mountain-card-${mountain.id}`}
    43|      >
    44|        <View style={styles.leftSection}>
    45|          <View style={[styles.iconContainer, { backgroundColor: categoryColor + '20' }]}>
    46|            <MountainIcon category={mountain.category} difficulty={mountain.difficulty} size={24} />
    47|          </View>
    48|        </View>
    49|
    50|        <View style={styles.centerSection}>
    51|          <View style={styles.nameRow}>
    52|            <Text style={styles.name} numberOfLines={1}>{mountain.name}</Text>
    53|            {isSummited && (
    54|              <CheckCircle color={Colors.success} size={16} />
    55|            )}
    56|          </View>
    57|          <Text style={styles.location} numberOfLines={1}>
    58|            {mountain.country} · {mountain.range}
    59|          </Text>
    60|          <View style={styles.tagRow}>
    61|            <View style={[styles.categoryTag, { backgroundColor: categoryColor + '25', borderColor: categoryColor + '40' }]}>
    62|              <Text style={[styles.categoryTagText, { color: categoryColor }]}>
    63|                {categoryLabels[mountain.category]}
    64|              </Text>
    65|            </View>
    66|            <View style={styles.difficultyTag}>
    67|              <Text style={styles.difficultyText}>{mountain.difficulty}</Text>
    68|            </View>
    69|          </View>
    70|        </View>
    71|
    72|        <View style={styles.rightSection}>
    73|          <Text style={styles.elevation}>{mountain.elevation.toLocaleString()}m</Text>
    74|          <Text style={styles.elevationFt}>{mountain.elevationFt.toLocaleString()}ft</Text>
    75|          <ChevronRight color={Colors.textMuted} size={16} />
    76|        </View>
