                ) : (
                  <>
                    <Calendar color={Colors.accent} size={40} />
                    <Text style={styles.dateTitle}>When did you summit?</Text>

                    <View style={styles.datePickerRow}>
                      <View style={styles.datePickerCol}>
                        <Text style={styles.datePickerLabel}>Month</Text>
